/**
 * Real-document regression for the Class XI Physics paper.
 *
 * These tests read the actual PDF bytes in tests/fixtures/physics (a two-page
 * PDF with a real text layer and an image-only scan), not a hand-written
 * string. The PDF is generated by scripts/make-physics-fixtures.ts and its
 * structure follows the reported paper: sections 3 + 6 + 16 = 25, Q6 and Q7 at
 * 2 + 3 + 3.
 */
import { describe, expect, it } from 'vitest';
import { readFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { normaliseExtractedText, reconstructPageLines } from '../src/extraction/layout';
import { parsePaper } from '../src/exam/paper';
import { evaluatePaper } from '../src/exam/grade';
import { decisionChat } from './helpers';

const PDF = 'tests/fixtures/physics/physics-paper.pdf';
const SCAN = 'tests/fixtures/physics/physics-paper-scan.pdf';
const available = existsSync(PDF) && existsSync(SCAN);

async function readPdf(file: string) {
  const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs');
  const data = new Uint8Array(await readFile(file));
  const pdf = await pdfjs.getDocument({ data, isEvalSupported: false, useSystemFonts: true }).promise;
  const pages: string[] = [];
  let textCharacters = 0;
  try {
    for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber++) {
      const page = await pdf.getPage(pageNumber);
      const content = await page.getTextContent();
      const items = content.items.flatMap(item => {
        if (!('str' in item) || !Array.isArray((item as { transform?: unknown }).transform)) return [];
        const record = item as unknown as { str: string; transform: number[]; width?: number; height?: number };
        textCharacters += record.str.length;
        return [{ str: record.str, transform: record.transform, width: record.width, height: record.height }];
      });
      pages.push(reconstructPageLines(items));
      page.cleanup();
    }
  } finally {
    await pdf.destroy();
  }
  return { text: normaliseExtractedText(pages.join('\n\n')), pages: pdf.numPages ?? 0, textCharacters };
}

describe.skipIf(!available)('Class XI Physics paper: real PDF', () => {
  it('reads a two-page PDF and recognises Q1–Q7 with 25 marks', async () => {
    const { text, textCharacters } = await readPdf(PDF);
    const paper = parsePaper(text);
    console.log('[physics pdf]\n' + text.slice(0, 1500));
    console.log(paper.questions.map(question => `${question.ref}=${question.max}`).join(' '), '| total', paper.resolvedTotal);
    expect(textCharacters).toBeGreaterThan(400);
    expect(paper.questions.map(question => question.ref)).toEqual([
      'Q1',
      'Q2',
      'Q3',
      'Q4',
      'Q5',
      'Q6(a)',
      'Q6(b)',
      'Q6(c)',
      'Q7(a)',
      'Q7(b)',
      'Q7(c)',
    ]);
    expect(paper.resolvedTotal).toBe(25);
    expect(paper.printedTotal).toBe(25);
    expect(paper.unresolvedRefs).toEqual([]);
    expect(paper.questions.filter(question => question.key.startsWith('6')).reduce((sum, question) => sum + (question.max ?? 0), 0)).toBe(8);
    expect(paper.questions.filter(question => question.key.startsWith('7')).reduce((sum, question) => sum + (question.max ?? 0), 0)).toBe(8);
  });

  it('keeps a question that wraps onto the next line as one question', async () => {
    const { text } = await readPdf(PDF);
    const paper = parsePaper(text);
    expect(text).toMatch(/Taking\ng = 10 m\/s2, calculate its maximum height\. 1/);
    expect(paper.questions.find(question => question.ref === 'Q3')?.text).toContain('calculate its maximum height');
    expect(paper.questions.some(question => question.text === 'g = 10 m/s2, calculate its maximum height.')).toBe(false);
  });

  it('marks the real PDF end to end, from bytes to a report out of 25', async () => {
    const { text } = await readPdf(PDF);
    const paper = parsePaper(text);
    const answers = `Q1. (b) velocity
Q2. (c) acceleration
Q3. H = u^2/2g = 20 m
Q4. F = dp/dt = ma
Q5. W = F s, joule
Q6. (a) T = 2 s. (b) H = 5 m. (c) R = 34.6 m.
Q7. (a) Weight 50 N down, normal 50 N up, applied 25 N forward, friction 15 N backward. (b) f = 0.3 x 50 = 15 N. (c) a = 10/5 = 2 m/s2.`;
    const report = await evaluatePaper({
      paper,
      answerText: answers,
      board: 'CBSE',
      grade: 'Class 11',
      chat: decisionChat((_ref, max) => ({ awarded: max, feedback: 'Correct part, credited against the printed maximum.' })),
    });
    expect(report.paperTotal).toBe(25);
    expect(report.gradedCount).toBe(11);
    expect(report.awarded).toBe(25);
    expect(report.complete).toBe(true);
    expect(Math.round((report.awarded / report.paperTotal) * 100)).toBe(100);
  });

  it('treats the scanned PDF as a real scan with no text layer', async () => {
    const { textCharacters } = await readPdf(SCAN);
    expect(textCharacters).toBe(0);
  });
});
